import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"CLI Reference — OpenShield-L7","description":"Every openshield-l7 command — run, validate, gen-token, gen-cert — with global flags, examples, and sample output.","frontmatter":{"title":"CLI Reference — OpenShield-L7","description":"Every openshield-l7 command — run, validate, gen-token, gen-cert — with global flags, examples, and sample output."},"headers":[],"relativePath":"openshield-l7/user-guide/cli.md","filePath":"openshield-l7/user-guide/cli.md","lastUpdated":1786524249000}'),i={name:"openshield-l7/user-guide/cli.md"};function l(o,e,d,p,c,r){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><p>The <code>openshield-l7</code> binary has four subcommands. With no subcommand given, it defaults to <code>run</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openshield-l7 [--root DIR] [--config FILE] &lt;COMMAND&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>  run        Load configs and start the proxy (default)</span></span>
<span class="line"><span>  validate   Parse + validate the global config and every site file, then exit non-zero if anything is invalid</span></span>
<span class="line"><span>  gen-token  Print a fresh random API token and the YAML snippet to paste</span></span>
<span class="line"><span>  gen-cert   Generate a self-signed dev certificate (fullchain.pem + privkey.pem)</span></span></code></pre></div><h2 id="global-flags" tabindex="-1">Global flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to &quot;Global flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--root DIR</code></td><td><code>.</code></td><td>Project root containing <code>config.yaml</code> and <code>sites.d/</code>.</td></tr><tr><td><code>--config FILE</code></td><td><code>&lt;root&gt;/config.yaml</code></td><td>Global config file. Relative paths resolve inside <code>--root</code>; absolute paths are used as-is.</td></tr></tbody></table><p>Both flags are global — they work with every subcommand (<code>openshield-l7 --root /etc/openshield-l7 validate</code>).</p><hr><h2 id="run" tabindex="-1"><code>run</code> <a class="header-anchor" href="#run" aria-label="Permalink to &quot;\`run\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--root </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DIR]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--config </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FILE]</span></span></code></pre></div><p>Loads the global config and every site file, then starts the proxy, the admin API, the metrics engine, the limit-maintenance task, and the hot-reload watcher.</p><p>Startup behavior:</p><ul><li><strong>First-run bootstrap</strong> — if <code>config.yaml</code> is missing, a fully-commented default is written (mode <code>0600</code>) with one generated admin token printed <strong>once</strong> to stdout (never logged). <code>data/</code> and <code>sites.d/</code> are created; an empty <code>sites.d/</code> gets a commented <code>example.yaml.disabled</code> template.</li><li><strong>Per-file isolation at load</strong> — every <code>sites.d/*.yaml</code> is parsed and validated independently; failures are logged and skipped, the rest still serve.</li><li><strong>Empty site <code>id</code></strong> — the loader assigns a uuid and rewrites the file with it.</li><li><strong>Hostname conflicts</strong> between enabled sites are first-wins (sorted order); the later file is logged and skipped.</li><li><strong>Challenge secret</strong> — <code>data/challenge.secret</code> (hex, mode <code>0600</code>) is loaded or generated so clearance cookies survive restarts; a corrupt file is regenerated with a warning (existing clearances are invalidated).</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># typical systemd invocation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/openshield-l7</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># unprivileged dev run on high ports (edit config to 8080/8443 first)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>Shutdown: <code>SIGTERM</code>/<code>SIGINT</code> stops accepting and drains gracefully (bounded), exit code <code>0</code>. If the proxy or admin API dies on its own (e.g. bind failure), the process exits <code>1</code> — under systemd that&#39;s <code>Restart=on-failure</code> territory.</p><p><strong>When to use:</strong> always — this is the daemon. For preflight checks without starting, use <code>validate</code>.</p><hr><h2 id="validate" tabindex="-1"><code>validate</code> <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;\`validate\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--root </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DIR]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--config </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FILE]</span></span></code></pre></div><p>Parses and validates <code>config.yaml</code> and every <code>sites.d/*.yaml</code>, printing <strong>every</strong> problem (not just the first), then exits non-zero if anything is invalid. Also reports cross-file issues: duplicate site ids and duplicate hostnames between enabled sites.</p><p>Sample output — all good:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OK   /etc/openshield-l7/config.yaml</span></span>
<span class="line"><span>OK   /etc/openshield-l7/sites.d/example.yaml</span></span>
<span class="line"><span>OK   /etc/openshield-l7/sites.d/shop.yaml</span></span>
<span class="line"><span>all configs valid (config.yaml + 2 site file(s) in /etc/openshield-l7/sites.d)</span></span></code></pre></div><p>Sample output — problems:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OK   /etc/openshield-l7/config.yaml</span></span>
<span class="line"><span>FAIL /etc/openshield-l7/sites.d/broken.yaml: origin.url: &#39;http://&#39;: missing host</span></span>
<span class="line"><span>FAIL /etc/openshield-l7/sites.d/dup.yaml: hostname &#39;example.com&#39; also claimed by /etc/openshield-l7/sites.d/example.yaml</span></span>
<span class="line"><span>2 problem(s) found</span></span></code></pre></div><p><strong>When to use:</strong> in CI before shipping config changes, after hand edits, and as step one of every upgrade (<code>validate</code> against the new binary before restarting). Exit code makes it scriptable: <code>openshield-l7 validate || exit 1</code>.</p><hr><h2 id="gen-token" tabindex="-1"><code>gen-token</code> <a class="header-anchor" href="#gen-token" aria-label="Permalink to &quot;\`gen-token\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen-token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NAME]</span></span></code></pre></div><p>Prints a fresh random API token plus the ready-to-paste YAML. <code>--name</code> defaults to <code>admin</code> and is only a label (used in logs, never the secret).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ openshield-l7 gen-token --name bootstrap</span></span>
<span class="line"><span>Generated admin API token:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  name:  bootstrap</span></span>
<span class="line"><span>  token: 7f3c9e1a-2b4d-4e8f-9a1c-5d6e7f8091a2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Paste into config.yaml:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>admin:</span></span>
<span class="line"><span>  tokens:</span></span>
<span class="line"><span>    - name: &quot;bootstrap&quot;</span></span>
<span class="line"><span>      token: &quot;7f3c9e1a-2b4d-4e8f-9a1c-5d6e7f8091a2&quot;</span></span>
<span class="line"><span>      role: admin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Store it somewhere safe; openshield-l7 never logs token values.</span></span></code></pre></div><p><strong>When to use:</strong> bootstrap, adding a dashboard (<code>--name dashboard</code>, then change <code>role:</code> to <code>readonly</code>), and rotation. Note the snippet always prints <code>role: admin</code> — downgrade it yourself for less-privileged tokens. Hot reload means a pasted token is live within a second; no restart.</p><hr><h2 id="gen-cert" tabindex="-1"><code>gen-cert</code> <a class="header-anchor" href="#gen-cert" aria-label="Permalink to &quot;\`gen-cert\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen-cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HOSTNAME</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DIR</span></span></code></pre></div><p>Writes a self-signed dev certificate pair (<code>fullchain.pem</code> mode <code>0644</code>, <code>privkey.pem</code> mode <code>0600</code>) with <code>HOSTNAME</code> as the SAN, plus the matching site-config snippet. <code>--host</code> must be non-empty; the output directory is created if needed.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ openshield-l7 gen-cert --host example.com --out ./certs/example.com</span></span>
<span class="line"><span>Wrote a self-signed dev certificate for &#39;example.com&#39;:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  cert: ./certs/example.com/fullchain.pem</span></span>
<span class="line"><span>  key:  ./certs/example.com/privkey.pem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Site config snippet:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tls:</span></span>
<span class="line"><span>  enabled: true</span></span>
<span class="line"><span>  cert_path: &quot;./certs/example.com/fullchain.pem&quot;</span></span>
<span class="line"><span>  key_path: &quot;./certs/example.com/privkey.pem&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Self-signed: browsers will warn; use a real CA for production.</span></span></code></pre></div><p><strong>When to use:</strong> local TLS testing and staging — SNI routing, HSTS, and the 308 redirect all behave identically to a real cert. <strong>Never</strong> for production; browsers will warn.</p><hr><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>Success — clean <code>validate</code>, or <code>run</code> stopped by signal and drained.</td></tr><tr><td><code>1</code></td><td>Any validation problem (<code>validate</code>), or <code>run</code> died from an internal failure (bind error, config load error, proxy/API task death).</td></tr></tbody></table><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th></tr></thead><tbody><tr><td><code>RUST_LOG</code></td><td>Overrides <code>log_level</code> from <code>config.yaml</code> (e.g. <code>RUST_LOG=debug openshield-l7 run</code>). When unset, the config value wins.</td></tr></tbody></table>`,41)])])}const u=s(i,[["render",l]]);export{g as __pageData,u as default};
